// Clinical Concept Extractionの結果を取得
const analysis = $("Analyze Clinical Question").first().json.output;

// Trusted Sourcesシートから取得した全行
const sourceRows = $input.all().map(item => item.json);

// Guideline domainsを正規化
const guidelineDomains =
  analysis.normalized_concepts?.guideline_domains ?? [];

const targetRegion = analysis.target_region ?? "";

// Active列の値をBooleanとして判定する関数
function isActive(value) {
  if (value === true) return true;

  const normalized = String(value ?? "")
    .trim()
    .toLowerCase();

  return ["true", "yes", "1", "active"].includes(normalized);
}

// Target Regionの情報源
const regionalSources = sourceRows.filter(row => {
  return (
    guidelineDomains.includes(row["Guideline Domain"]) &&
    row["Region"] === targetRegion &&
    isActive(row["Active"])
  );
});

// Globalの情報源
const globalSources = sourceRows.filter(row => {
  return (
    guidelineDomains.includes(row["Guideline Domain"]) &&
    row["Region"] === "Global" &&
    isActive(row["Active"])
  );
});

// 地域内のPriorityを優先して並べる
regionalSources.sort(
  (a, b) => Number(a["Priority"]) - Number(b["Priority"])
);

globalSources.sort(
  (a, b) => Number(a["Priority"]) - Number(b["Priority"])
);

// 地域情報源を先にし、Globalを後に追加
const matchedSources = [
  ...regionalSources,
  ...globalSources,
].map(row => ({
  guideline_domain: row["Guideline Domain"],
  region: row["Region"],
  priority: Number(row["Priority"]),
  organization: row["Organization"],
  domain: row["Domain"],
  source_type: row["Source Type"],
}));

return [
  {
    json: {
      ...analysis,
      source_mapping: {
        matched_domains: guidelineDomains,
        target_region: targetRegion,
        regional_source_count: regionalSources.length,
        global_source_count: globalSources.length,
        matched_sources: matchedSources,
      },
    },
  },
];

const input = $input.first().json;
const searchResults = input.search_results ?? [];

/**
 * タイトル・説明・URLから発行年を抽出します。
 * 複数の年がある場合は、原則として最も新しい年を採用します。
 */
function extractPublicationYear(text) {
  const currentYear = new Date().getFullYear();

  const years = String(text ?? "")
    .match(/\b(19|20)\d{2}\b/g)
    ?.map(Number)
    .filter(
      (year) =>
        year >= 1900 &&
        year <= currentYear + 1
    );

  return years?.length
    ? Math.max(...years)
    : null;
}

/**
 * 文書種別を暫定分類します。
 *
 * 判定順が重要です。
 * 1. 学術誌
 * 2. 声明
 * 3. 包括的ガイドライン
 * 4. 分野別ガイドライン
 * 5. その他のエビデンス
 */
function classifyDocumentType(title, description, url) {
  const titleText = String(title ?? "");
  const fullText =
    `${title ?? ""} ${description ?? ""} ${url ?? ""}`;

  const normalizedTitle = titleText.toLowerCase();
  const normalizedFullText = fullText.toLowerCase();

  // 学術誌の号・目次ページ
  if (
    /\bvol\.?\s*\d+/i.test(titleText) ||
    /\bno\.?\s*\d+/i.test(titleText) ||
    /\b(january|february|march|april|may|june|july|august|september|october|november|december)\b/i.test(
      titleText
    )
  ) {
    return "journal_issue";
  }

  // 声明・緊急声明
  if (
    /緊急声明|声明|statement|position statement|expert statement/i.test(
      titleText
    )
  ) {
    return "statement";
  }

  // 包括的な診療ガイドライン
  if (
    /診療ガイドライン/i.test(titleText) ||
    /治療ガイドライン/i.test(titleText) ||
    /管理・治療ガイドライン/i.test(titleText) ||
    /clinical practice guideline/i.test(normalizedTitle) ||
    /practice guideline/i.test(normalizedTitle)
  ) {
    return "comprehensive_guideline";
  }

  // 特定治療・手技・領域に関する指針
  if (
    /適正治療指針/i.test(titleText) ||
    /適正使用指針/i.test(titleText) ||
    /リハビリテーションの指針/i.test(titleText) ||
    /治療指針/i.test(titleText) ||
    /診療指針/i.test(titleText) ||
    /guideline/i.test(normalizedTitle) ||
    /guidance/i.test(normalizedTitle)
  ) {
    return "focused_guideline";
  }

  // タイトル以外の説明文などからのみ判定できる候補
  if (
    /ガイドライン|指針|guideline|guidance/i.test(
      normalizedFullText
    )
  ) {
    return "guideline_candidate";
  }

  if (
    /consensus|コンセンサス/i.test(
      normalizedFullText
    )
  ) {
    return "consensus_statement";
  }

  if (
    /systematic review|meta-analysis|meta analysis|システマティックレビュー|メタアナリシス/i.test(
      normalizedFullText
    )
  ) {
    return "systematic_review";
  }

  if (
    /randomized|randomised|randomized controlled trial|\brct\b|無作為化比較試験/i.test(
      normalizedFullText
    )
  ) {
    return "randomized_controlled_trial";
  }

  if (
    /cohort|observational|registry|case-control|観察研究|コホート/i.test(
      normalizedFullText
    )
  ) {
    return "observational_study";
  }

  return "other";
}

/**
 * 検索結果を分類します。
 */
const classifiedResults = searchResults.map((result) => {
  const combinedText = [
    result.title,
    result.description,
    result.url,
  ].join(" ");

  const publicationYear =
    extractPublicationYear(combinedText);

  const documentType =
    classifyDocumentType(
      result.title,
      result.description,
      result.url
    );

  return {
    ...result,
    publication_year: publicationYear,
    document_type: documentType,
    classification_status: "provisional",
    candidate_role: "",
  };
});

/**
 * 文書種別の優先順位
 *
 * 数字が小さいほど優先されます。
 */
const documentTypePriority = {
  comprehensive_guideline: 1,
  focused_guideline: 2,
  guideline_candidate: 3,
  consensus_statement: 4,
  statement: 5,
  systematic_review: 6,
  randomized_controlled_trial: 7,
  observational_study: 8,
  journal_issue: 9,
  other: 10,
};

/**
 * Primary Guideline候補として扱う文書種別
 */
const guidelineTypes = [
  "comprehensive_guideline",
  "focused_guideline",
  "guideline_candidate",
];

/**
 * Primary Guideline候補を並べ替えます。
 *
 * 優先順：
 * 1. 文書種別
 * 2. 発行年
 * 3. Brave検索順位
 */
const guidelineCandidates = classifiedResults
  .filter((result) =>
    guidelineTypes.includes(result.document_type)
  )
  .sort((a, b) => {
    const typeA =
      documentTypePriority[a.document_type] ?? 99;

    const typeB =
      documentTypePriority[b.document_type] ?? 99;

    if (typeA !== typeB) {
      return typeA - typeB;
    }

    const yearA =
      a.publication_year ?? 0;

    const yearB =
      b.publication_year ?? 0;

    if (yearA !== yearB) {
      return yearB - yearA;
    }

    const rankA =
      Number.isFinite(Number(a.rank))
        ? Number(a.rank)
        : 999;

    const rankB =
      Number.isFinite(Number(b.rank))
        ? Number(b.rank)
        : 999;

    return rankA - rankB;
  });

/**
 * Primary Guidelineを1件決定します。
 */
if (guidelineCandidates.length > 0) {
  guidelineCandidates[0].candidate_role =
    "current_guideline_candidate";

  for (
    let i = 1;
    i < guidelineCandidates.length;
    i++
  ) {
    guidelineCandidates[i].candidate_role =
      "older_guideline_candidate";
  }
}

/**
 * ガイドライン以外の候補に役割を付けます。
 */
for (const result of classifiedResults) {
  if (result.candidate_role !== "") {
    continue;
  }

  switch (result.document_type) {
    case "consensus_statement":
    case "systematic_review":
    case "randomized_controlled_trial":
    case "observational_study":
      result.candidate_role =
        "supplementary_evidence_candidate";
      break;

    case "statement":
      result.candidate_role =
        "statement_candidate";
      break;

    case "journal_issue":
      result.candidate_role =
        "journal_issue_candidate";
      break;

    case "guideline_candidate":
      result.candidate_role =
        "guideline_candidate";
      break;

    default:
      result.candidate_role =
        "unclassified_candidate";
  }
}

/**
 * guidelineCandidates側で付けた役割を
 * 元配列へ反映します。
 */
const roleByUrl = new Map(
  guidelineCandidates.map((result) => [
    result.url,
    result.candidate_role,
  ])
);

const finalResults = classifiedResults.map(
  (result) => ({
    ...result,
    candidate_role:
      roleByUrl.get(result.url) ??
      result.candidate_role,
  })
);

/**
 * 選択されたPrimary Guideline
 */
const selectedGuideline =
  finalResults.find(
    (result) =>
      result.candidate_role ===
      "current_guideline_candidate"
  ) ?? null;

/**
 * 集計
 */
const classificationSummary = {
  total_candidates:
    finalResults.length,

  guideline_candidates:
    finalResults.filter(
      (result) =>
        guidelineTypes.includes(
          result.document_type
        )
    ).length,

  comprehensive_guideline_candidates:
    finalResults.filter(
      (result) =>
        result.document_type ===
        "comprehensive_guideline"
    ).length,

  focused_guideline_candidates:
    finalResults.filter(
      (result) =>
        result.document_type ===
        "focused_guideline"
    ).length,

  statement_candidates:
    finalResults.filter(
      (result) =>
        result.document_type ===
        "statement"
    ).length,

  supplementary_candidates:
    finalResults.filter(
      (result) =>
        result.candidate_role ===
        "supplementary_evidence_candidate"
    ).length,

  journal_issue_candidates:
    finalResults.filter(
      (result) =>
        result.document_type ===
        "journal_issue"
    ).length,

  current_guideline_found:
    Boolean(selectedGuideline),

  selected_guideline_title:
    selectedGuideline?.title ?? "",

  selected_guideline_url:
    selectedGuideline?.url ?? "",

  selected_guideline_year:
    selectedGuideline?.publication_year ?? null,

  selected_guideline_type:
    selectedGuideline?.document_type ?? "",
};

return [
  {
    json: {
      ...input,
      classification_summary:
        classificationSummary,
      classified_results:
        finalResults,
    },
  },
];

// Fetch Guideline Metadata Page の結果
const response = $input.first().json;

// 前段のガイドライン選択結果と検索情報
const previous =
  $("Select Current Guideline").first().json;

const html = String(response.data ?? "");

// HTMLエンティティを最低限デコード
function decodeHtml(text) {
  return String(text ?? "")
    .replace(/&nbsp;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">");
}

// HTMLタグを除去して可視テキストへ変換
function stripHtml(value) {
  return decodeHtml(
    String(value ?? "")
      .replace(/<script[\s\S]*?<\/script>/gi, " ")
      .replace(/<style[\s\S]*?<\/style>/gi, " ")
      .replace(/<!--[\s\S]*?-->/g, " ")
      .replace(/<br\s*\/?>/gi, "\n")
      .replace(/<\/p>/gi, "\n")
      .replace(/<\/h[1-6]>/gi, "\n")
      .replace(/<[^>]+>/g, " ")
  )
    .replace(/[ \t]+/g, " ")
    .replace(/\n\s+/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

function firstMatch(pattern, source) {
  const match = String(source ?? "").match(pattern);
  return match?.[1] ? stripHtml(match[1]) : "";
}

// ページタイトル
const pageTitle =
  firstMatch(/<title[^>]*>([\s\S]*?)<\/title>/i, html) ||
  previous.guideline_selection?.selected_title ||
  "";

// ガイドライン名
const guidelineNameMatch = html.match(
  /(高血圧管理・治療ガイドライン\s*20\d{2})/
);

const guidelineName =
  guidelineNameMatch?.[1] ??
  previous.guideline_selection?.selected_title ??
  "";

// 発行年
const years = [
  ...stripHtml(html).matchAll(/\b(19|20)\d{2}\b/g),
]
  .map((match) => Number(match[0]))
  .filter(
    (year) =>
      year >= 1900 &&
      year <= new Date().getFullYear() + 1
  );

const publicationYear =
  previous.guideline_selection?.publication_year ??
  (years.length ? Math.max(...years) : null);

// 章見出し
const chapterMatches = [
  ...stripHtml(html).matchAll(/第(\d+)章\s*([^\n]+)/g),
];

const chapters = chapterMatches.map((match) => ({
  chapter_number: Number(match[1]),
  chapter_title: match[2].trim(),
}));

// ページ内リンク
const linkMatches = [
  ...html.matchAll(
    /<a[^>]+href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi
  ),
];

const baseUrl =
  previous.guideline_selection?.selected_url ?? "";

const links = linkMatches.map((match) => {
  const href = match[1];

  let absoluteUrl = href;

  try {
    absoluteUrl = new URL(href, baseUrl).toString();
  } catch {
    absoluteUrl = href;
  }

  return {
    text: stripHtml(match[2]),
    url: absoluteUrl,
  };
});

// 公開補助資料らしいPDFを抽出
// 正誤表・COI・転載申請などは除外
const excludedPdfPatterns = [
  /errata/i,
  /正誤表/i,
  /coi/i,
  /利益相反/i,
  /転載/i,
  /permission/i,
];

const publicSupportingDocumentLinks = links.filter((link) => {
  const combined = `${link.text} ${link.url}`;

  const isPdf = /\.pdf(?:$|\?)/i.test(link.url);

  const excluded = excludedPdfPatterns.some((pattern) =>
    pattern.test(combined)
  );

  return isPdf && !excluded;
});

// 公開ページの可視テキスト
const visibleText = stripHtml(html);

return [
  {
    json: {
      ...previous,

      guideline_metadata: {
        fetch_success: response.statusCode === 200,
        status_code: response.statusCode ?? null,
        content_type:
          response.headers?.["content-type"] ?? "",

        page_title: pageTitle,
        guideline_name: guidelineName,
        organization:
          "Japanese Society of Hypertension",
        publication_year: publicationYear,

        metadata_page_url: baseUrl,

        chapters,
        chapter_count: chapters.length,

        public_supporting_documents_available:
          publicSupportingDocumentLinks.length > 0,

        public_supporting_document_links:
          publicSupportingDocumentLinks,

        access_status:
          publicSupportingDocumentLinks.length > 0
            ? "supporting_documents_available"
            : "metadata_or_purchase_page_only",

        public_page_text_excerpt:
          visibleText.slice(0, 6000),
      },
    },
  },
];

const report = $input.first().json.output;

function section(title, body = "") {
  return `
==================================================
${title}
==================================================

${body}
`;
}

function bullet(items) {
  if (!items || items.length === 0) {
    return "None";
  }

  return items.map(i => `• ${i}`).join("\n");
}

const relevantSections =
(report.relevant_sections ?? [])
.map(s =>

`Chapter ${s.chapter_number}

${s.chapter_title}

Reason:
${s.relevance}

Evidence Basis:
${s.evidence_basis}

`
)
.join("\n----------------------------------------\n");

const references =
(report.references ?? [])
.map(r =>

`${r.title}

Organization:
${r.organization}

Year:
${r.year}

URL:
${r.url}

Type:
${r.source_type}
`
)
.join("\n----------------------------------------\n");

const additionalSources =
(report.additional_trusted_sources ?? [])
.map(r =>

`${r.organization}

Region:
${r.region}

Type:
${r.source_type}

Reviewed:
${r.content_reviewed}
`
)
.join("\n----------------------------------------\n");

const body = `

==================================================
Evidence-Based Clinical Guidance Report
==================================================

Generated by AI Medical Guideline Assistant

Generation Date:
${new Date().toISOString().slice(0,10)}

Target Region:
${report.target_region}

Output Language:
${report.output_language}

${section(
"Clinical Question",
report.clinical_question
)}

${section(
"Clinical Summary",
report.answer.summary
)}

${section(
"Confirmed Information",
bullet(report.answer.confirmed_points)
)}

${section(
"Information Not Confirmed",
bullet(report.answer.unconfirmed_or_unavailable_points)
)}

${section(
"Primary Guideline",

`Title:
${report.primary_guideline.title}

Organization:
${report.primary_guideline.organization}

Publication Year:
${report.primary_guideline.publication_year}

URL:
${report.primary_guideline.url}

Access Status:
${report.primary_guideline.access_status}

Full Text Reviewed:
${report.primary_guideline.full_text_reviewed}

Reason Selected:
${report.primary_guideline.why_prioritized}`
)}

${section(
"Relevant Guideline Sections",
relevantSections
)}

${section(
"Evidence Gaps",
bullet(report.evidence_gaps)
)}

${section(
"Limitations",
bullet(report.limitations)
)}

${section(
"Items to Verify in Original Guideline",
bullet(report.what_to_verify_in_original_guideline)
)}

${section(
"Additional Trusted Sources",
additionalSources
)}

${section(
"References",
references
)}

${section(
"Disclaimer",
report.disclaimer
)}
`;

const documentTitle =
`Clinical Guidance Report - ${report.target_region} - ${new Date().toISOString().slice(0,10)}`;

return [
{
json:{
document_title:documentTitle,
document_body:body
}
}
];

const MAX_RESULTS = 5;

// Search Braveノードから受け取ったJSON
const input = $input.first().json;

// Brave検索結果の先頭5件
const results = (input.web?.results ?? []).slice(0, MAX_RESULTS);

// 検索情報
const query = input.query?.original ?? "";
const restrictedDomains =
  input.query?.search_operators?.sites ?? [];

// 明らかなノイズ
const excludedPatterns = [
  /guide to authors/i,
  /instructions for authors/i,
  /投稿規定/i,
  /学術委員会/i,
  /一般向け/i,
  /わかりやすい解説/i,
];

const normalizedResults = results
  .map((result, index) => {
    const title = result.title ?? "";
    const description = result.description ?? "";
    const url = result.url ?? "";

    // Braveが返すhostnameを優先
    let hostname =
      result.meta_url?.hostname ??
      result.profile?.long_name ??
      "";

    hostname = String(hostname)
      .trim()
      .toLowerCase()
      .replace(/^www\./, "");

    const isPdf =
      result.content_type === "pdf" ||
      url.toLowerCase().endsWith(".pdf");

    const excluded = excludedPatterns.some(
      (pattern) =>
        pattern.test(title) ||
        pattern.test(url)
    );

    return {
      rank: index + 1,
      title,
      url,
      description,
      hostname,
      language: result.language ?? "",
      content_type: isPdf ? "pdf" : "html",
      excluded,
      exclusion_reason: excluded
        ? "Likely non-guideline or non-clinical content"
        : "",
    };
  })
  .filter((result) => {
    const domainAllowed =
      restrictedDomains.length === 0 ||
      restrictedDomains.some((domain) => {
        const normalizedDomain = String(domain)
          .trim()
          .toLowerCase()
          .replace(/^www\./, "");

        return (
          result.hostname === normalizedDomain ||
          result.hostname.endsWith(`.${normalizedDomain}`)
        );
      });

    return domainAllowed && !result.excluded;
  });

return [
  {
    json: {
      search_query: query,
      restricted_domains: restrictedDomains,
      total_raw_results: input.web?.results?.length ?? 0,
      analyzed_result_count: results.length,
      total_filtered_results: normalizedResults.length,
      search_results: normalizedResults,
    },
  },
];

const input = $input.first().json;

const candidates = input.classified_results ?? [];

const currentGuideline = candidates.find(
  (item) =>
    item.candidate_role === "current_guideline_candidate"
);

if (!currentGuideline) {
  return [
    {
      json: {
        ...input,
        guideline_selection: {
          found: false,
          reason: "No current guideline candidate was found.",
          selected_title: "",
          selected_url: "",
          publication_year: null,
          content_type: "",
          hostname: "",
          document_type: "",
          search_rank: null,
        },
      },
    },
  ];
}

return [
  {
    json: {
      ...input,
      guideline_selection: {
        found: true,
        selected_title: currentGuideline.title ?? "",
        selected_url: currentGuideline.url ?? "",
        publication_year:
          currentGuideline.publication_year ?? null,
        content_type:
          currentGuideline.content_type ?? "",
        hostname:
          currentGuideline.hostname ?? "",
        document_type:
          currentGuideline.document_type ?? "",
        search_rank:
          currentGuideline.rank ?? null,
      },
    },
  },
];

const input = $input.first().json;

// Basic LLM Chainの出力形式に対応
let raw =
  input.text ??
  input.response?.generations?.[0]?.[0]?.text ??
  "";

raw = String(raw).trim();

// Markdownコードフェンスを除去
raw = raw
  .replace(/^```json\s*/i, "")
  .replace(/^```\s*/i, "")
  .replace(/\s*```$/i, "")
  .trim();

let parsed;

try {
  parsed = JSON.parse(raw);
} catch (error) {
  throw new Error(
    `Clinical guidance JSON parsing failed: ${error.message}`
  );
}

// outputラッパーが付いた場合にも対応
if (
  parsed &&
  typeof parsed === "object" &&
  parsed.output &&
  typeof parsed.output === "object"
) {
  parsed = parsed.output;
}

// 最低限の必須項目を確認
const requiredFields = [
  "clinical_question",
  "target_region",
  "output_language",
  "answer",
  "primary_guideline",
  "relevant_sections",
  "publicly_available_information",
  "recommendations",
  "additional_trusted_sources",
  "evidence_gaps",
  "limitations",
  "what_to_verify_in_original_guideline",
  "references",
  "disclaimer",
];

const missingFields = requiredFields.filter(
  (field) => !(field in parsed)
);

if (missingFields.length > 0) {
  throw new Error(
    `Clinical guidance JSON is missing required fields: ${missingFields.join(", ")}`
  );
}

return [
  {
    json: {
      output: parsed,
    },
  },
];
